INSERT INTO public.chapters (title, slug, track, order_num, summary, reading_time) VALUES
('Что такое блокчейн на самом деле', 'a1-blockchain-basics', 'technology', 1, 'Состояние, история и роль транзакций в общей системе.', 12),
('Криптография для крипты без матана', 'a2-crypto-basics', 'technology', 2, 'Хеши, ключи, подписи и Merkle деревья простым языком.', 14),
('P2P сеть и жизненный цикл транзакции', 'a3-transaction-lifecycle', 'technology', 3, 'Как транзакции распространяются, подтверждаются и получают финальность.', 12),
('Консенсус', 'a4-consensus', 'technology', 4, 'Почему сети договариваются, даже когда участники недоверчивы.', 13),
('Модели учета', 'a5-ledger-models', 'technology', 5, 'UTXO и account модель: разные способы представления состояния.', 11),
('Смарт контракты и токены', 'a6-smart-contracts', 'technology', 6, 'Идея программируемых правил и токенов, а также слабые места.', 14),
('Масштабирование и L2', 'a7-scaling-l2', 'technology', 7, 'Почему масштабирование сложно и как работают rollups.', 13),
('Безопасность и модель угроз', 'a8-security', 'technology', 8, 'Где реально теряются средства и как думать о рисках.', 12),
('Кошелек = управление ключами', 'b1-wallet-keys', 'wallets', 1, 'Seed phrase, хранение и типы кошельков.', 10),
('Подпись и разрешения', 'b2-signatures-permissions', 'wallets', 2, 'Что вы подписываете и как работают allowances.', 11),
('Биржи как инфраструктура', 'c1-exchanges-infra', 'exchanges', 1, 'CEX и DEX, ввод и вывод, комиссии и выбор сети.', 12);
INSERT INTO public.sections (chapter_id, title, slug, order_num, content_json) VALUES
((SELECT id FROM public.chapters WHERE slug = 'a1-blockchain-basics'), 'Состояние и история', 'state-vs-history', 1, '[{"type": "paragraph", "text": "Блокчейн хранит историю изменений, но ключевым является текущее состояние системы. Транзакция переводит состояние из одного значения в другое, а блок фиксирует этот переход во времени.", "glossaryTermRefs": ["blockchain", "state", "transaction", "block"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Состояние отвечает на вопрос что есть сейчас, история показывает как мы к этому пришли."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Блокчейн не равен просто списку операций. Это согласованное состояние, которое можно проверить."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Если источник состояния подменен, пользователь видит ложный баланс. Всегда проверяйте сеть и источник данных."}, {"type": "figure", "figureType": "svg", "caption": "Состояние и история в блокчейне"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a1-blockchain-basics'), 'Транзакция как переход состояния', 'tx-state-transition', 2, '[{"type": "paragraph", "text": "Транзакция описывает правила изменения состояния: кто отправляет, кому и какие ограничения действуют. Важно понимать, что транзакция сама по себе не результат, а запрос на изменение.", "glossaryTermRefs": ["transaction", "state"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Сеть применяет транзакции детерминированно, поэтому результат должен быть одинаковым у всех узлов."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Отправка транзакции не гарантирует мгновенный результат. Она проходит через mempool и подтверждения."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Если вы подписали неверную транзакцию, сеть выполнит ее без вопросов. Проверяйте данные перед подписью."}, {"type": "figure", "figureType": "svg", "caption": "Переход состояния по шагам"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a2-crypto-basics'), 'Хеши и отпечатки', 'hashes-fingerprints', 1, '[{"type": "paragraph", "text": "Хеш функция превращает данные в короткий отпечаток. Это позволяет проверять целостность без раскрытия содержимого и строить структуры вроде Merkle дерева.", "glossaryTermRefs": ["hash", "hash-function", "merkle-tree"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Хеш связывает данные и их проверку: маленькое изменение меняет весь отпечаток."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Хеш не шифрование. Его нельзя использовать для скрытия информации."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Коллизии крайне редки, но плохая реализация хеша может привести к подмене данных."}, {"type": "figure", "figureType": "interactive", "caption": "Интерактив: Merkle proof", "refSlug": "merkle-proof-explorer"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a2-crypto-basics'), 'Ключи и подписи', 'keys-and-signatures', 2, '[{"type": "paragraph", "text": "Публичный ключ подтверждает, что подпись создана владельцем приватного ключа. Цифровая подпись доказывает авторство транзакции без раскрытия секрета.", "glossaryTermRefs": ["public-key", "private-key", "digital-signature"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Подпись доказывает контроль над ключом, а не личность человека."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Публичный ключ не раскрывает приватный. Безопасность держится на сложности математики."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Кража приватного ключа означает полный контроль над активами. Защищайте ключи как пароль от всего."}, {"type": "figure", "figureType": "interactive", "caption": "Интерактив: цифровая подпись", "refSlug": "digital-signature-steps"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a3-transaction-lifecycle'), 'P2P сеть и распространение', 'p2p-propagation', 1, '[{"type": "paragraph", "text": "Транзакции распространяются по P2P сети между узлами. Каждый узел проверяет валидность и передает транзакцию дальше, создавая быстрый волновой эффект.", "glossaryTermRefs": ["p2p-network", "node", "transaction"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Сеть не имеет единого центра, поэтому задержки зависят от маршрутов и нагрузки."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Если вы отправили транзакцию, это не значит что она уже в блоке."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Поддельные фронтенды могут показывать отправку, хотя транзакция не покинула устройство."}, {"type": "figure", "figureType": "svg", "caption": "Распространение транзакции по сети"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a3-transaction-lifecycle'), 'Mempool и подтверждения', 'mempool-confirmations', 2, '[{"type": "paragraph", "text": "Mempool это очередь неподтвержденных транзакций. Валидаторы выбирают транзакции по правилам сети и включают их в блок, после чего появляются подтверждения.", "glossaryTermRefs": ["mempool", "confirmation", "fee"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Подтверждения это нарастающая уверенность, что история не будет пересмотрена."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Нулевая комиссия не означает бесплатность. Сеть всегда выбирает более выгодные транзакции."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Низкая комиссия приводит к застреванию транзакции. Будьте внимательны при отправке срочных операций."}, {"type": "figure", "figureType": "interactive", "caption": "Интерактив: жизненный цикл транзакции", "refSlug": "transaction-lifecycle"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a4-consensus'), 'PoW vs PoS интуитивно', 'pow-vs-pos', 1, '[{"type": "paragraph", "text": "Консенсус определяет, кто имеет право создавать блоки. В Proof of Work это вычислительная работа, в Proof of Stake это ставка и ответственность валидаторов.", "glossaryTermRefs": ["consensus", "proof-of-work", "proof-of-stake", "validator"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Обе модели решают задачу согласования, но платят разной ценой: энергией или капиталом."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "PoS не означает что богатые всегда побеждают. Есть механизмы штрафов и ротации."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Плохие стимулы или концентрация валидаторов могут ослабить децентрализацию."}, {"type": "figure", "figureType": "svg", "caption": "Сравнение PoW и PoS"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a4-consensus'), 'Атаки и компромиссы', 'attacks-tradeoffs', 2, '[{"type": "paragraph", "text": "Сети сталкиваются с атаками на финальность, цензуру и двойную трату. Компромисс между скоростью и безопасностью определяется дизайном протокола.", "glossaryTermRefs": ["double-spend", "reorg", "slashing"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Безопасность консенсуса строится на экономических стимулах и проверяемости."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Высокая скорость не всегда означает лучшую сеть. Быстрые блоки могут снижать устойчивость."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Атака 51 процента приводит к пересмотру истории. Следите за глубиной подтверждений."}, {"type": "figure", "figureType": "svg", "caption": "Типовые атаки и компромиссы"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a5-ledger-models'), 'UTXO модель', 'utxo-model', 1, '[{"type": "paragraph", "text": "UTXO модель представляет баланс как набор непотраченных выходов. Транзакция потребляет старые выходы и создает новые, формируя цепочку расходования.", "glossaryTermRefs": ["utxo", "transaction"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "UTXO делает историю прозрачной и упрощает параллельную проверку."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "UTXO не значит что у пользователя один адрес. Адресов может быть много."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Повторное использование адресов снижает приватность и упрощает анализ."}, {"type": "figure", "figureType": "interactive", "caption": "Интерактив: UTXO vs account", "refSlug": "utxo-vs-account"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a5-ledger-models'), 'Account модель', 'account-model', 2, '[{"type": "paragraph", "text": "Account модель хранит баланс на счете. Транзакция изменяет баланс отправителя и получателя напрямую, а также учитывает nonce для защиты от повторов.", "glossaryTermRefs": ["account-model", "nonce"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Счетовая модель ближе к привычным банковским системам и упрощает работу контрактов."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Account модель не делает сеть централизованной. Это лишь способ учета."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Неверный nonce приводит к ошибкам или блокировке последующих транзакций."}, {"type": "figure", "figureType": "svg", "caption": "Account модель и баланс"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a6-smart-contracts'), 'Идея смарт контрактов', 'smart-contracts-idea', 1, '[{"type": "paragraph", "text": "Смарт контракт это код, который исполняется одинаково на всех узлах. Он задает правила токенов, протоколов и автоматических соглашений.", "glossaryTermRefs": ["smart-contract", "virtual-machine"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Код контракта прозрачен, но его ошибки также прозрачны и необратимы."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Смарт контракт не значит умный. Он просто детерминированно исполняет правила."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Уязвимый контракт может быть эксплуатирован без взлома инфраструктуры."}, {"type": "figure", "figureType": "svg", "caption": "Контракт как набор правил"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a6-smart-contracts'), 'Токены и оракулы', 'tokens-oracles', 2, '[{"type": "paragraph", "text": "Токены описывают права и учет активов, а оракулы вводят данные из внешнего мира. Оракулы являются слабым местом, потому что переносят доверие вне цепочки.", "glossaryTermRefs": ["token", "oracle"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Любые внешние данные требуют доверия к источнику, даже если контракт выглядит надежно."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Токен не обязательно означает инвестицию. Это может быть билет, доступ или право голоса."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Манипуляция оракулом может менять цены и разрушать протоколы."}, {"type": "figure", "figureType": "svg", "caption": "Токены и внешние источники данных"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a7-scaling-l2'), 'Почему масштабирование сложно', 'why-scaling-hard', 1, '[{"type": "paragraph", "text": "Рост числа пользователей увеличивает нагрузку на сеть. Ограничения пропускной способности и безопасности заставляют искать баланс между скоростью и проверяемостью.", "glossaryTermRefs": ["throughput", "scalability"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Нельзя бесконечно ускорять сеть, не жертвуя децентрализацией или безопасностью."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Больше блоков не всегда значит лучше. Это влияет на размер данных и доступность."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Если данные недоступны, пользователи не смогут проверить состояние."}, {"type": "figure", "figureType": "svg", "caption": "Треугольник масштабирования"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a7-scaling-l2'), 'Rollups и мосты', 'rollups-bridges', 2, '[{"type": "paragraph", "text": "Rollup собирает транзакции в пакет и публикует результат в L1. Мосты переносят активы между сетями, но являются зоной повышенного риска.", "glossaryTermRefs": ["rollup", "bridge", "layer-2"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "L2 наследует безопасность L1, если соблюдаются условия честной публикации данных."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Мост это не просто перевод. Это доверие к логике и операторам."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Большинство крупных взломов связано с мостами. Разделяйте риск и суммы."}, {"type": "figure", "figureType": "interactive", "caption": "Интерактив: поток rollup", "refSlug": "rollup-l2-flow"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a8-security'), 'Где реально крадут', 'where-losses-happen', 1, '[{"type": "paragraph", "text": "Чаще всего средства теряются из-за утечки ключей, фишинга и плохих approvals. Инфраструктурные взломы редки, но последствия масштабны.", "glossaryTermRefs": ["phishing", "private-key", "approval"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Основной риск находится на уровне пользователя и интерфейсов, а не базовой криптографии."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Если сеть надежна, это не означает что ваш кошелек защищен."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Фальшивые сайты имитируют интерфейс кошелька и перехватывают подписи."}, {"type": "figure", "figureType": "svg", "caption": "Типовые сценарии потерь"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'a8-security'), 'Модель угроз для пользователя', 'user-threat-model', 2, '[{"type": "paragraph", "text": "Модель угроз помогает понимать кто атакует, какие ресурсы у противника и какие данные защищать в первую очередь. Это дисциплина, а не список страхов.", "glossaryTermRefs": ["threat-model", "opsec"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Четкий список активов и сценариев помогает выстроить практичную защиту."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Безопасность не означает постоянную паранойю. Она про осознанные привычки."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Без плана восстановления даже мелкая ошибка может привести к потере доступа."}, {"type": "figure", "figureType": "svg", "caption": "Пример модели угроз"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'b1-wallet-keys'), 'Seed phrase и хранение', 'seed-storage', 1, '[{"type": "paragraph", "text": "Seed phrase это мастер ключ, из которого выводятся все адреса. Храните ее офлайн и разделяйте на независимые копии.", "glossaryTermRefs": ["seed-phrase", "backup", "private-key"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Кто владеет seed phrase, тот владеет всеми активами."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Скриншоты и облачные заметки не являются безопасным хранением."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Утечка seed phrase необратима. Проверяйте безопасность устройства и окружения."}, {"type": "figure", "figureType": "svg", "caption": "Схема безопасного хранения"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'b1-wallet-keys'), 'Hot vs cold и hardware', 'hot-cold-hardware', 2, '[{"type": "paragraph", "text": "Hot кошелек удобен для частых операций, cold кошелек используется для долгого хранения. Hardware кошелек удерживает ключи в изолированном устройстве.", "glossaryTermRefs": ["hot-wallet", "cold-wallet", "hardware-wallet"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Разделяйте средства по уровню риска и назначению."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Hardware кошелек не защищает от всех угроз, если вы подтверждаете неверную транзакцию."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Поддельные устройства и прошивки могут перехватить ключи. Покупайте у проверенных продавцов."}, {"type": "figure", "figureType": "svg", "caption": "Сравнение типов кошельков"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'b2-signatures-permissions'), 'Что вы подписываете', 'what-you-sign', 1, '[{"type": "paragraph", "text": "Подпись подтверждает конкретные параметры транзакции или сообщения. Читайте экран подтверждения, особенно адрес, сумму и сеть.", "glossaryTermRefs": ["digital-signature", "transaction", "gas"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Криптография не отличает добрые намерения от ошибок пользователя."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Подпись не означает вход в систему. Она означает согласие на действие."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Подмена адреса или сети приводит к потере средств без возможности возврата."}, {"type": "figure", "figureType": "svg", "caption": "Данные, которые подписывает кошелек"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'b2-signatures-permissions'), 'Approvals и типовые ошибки', 'approvals-mistakes', 2, '[{"type": "paragraph", "text": "Approvals дают контрактам право тратить ваши токены. Unlimited allowance удобно, но рискованно, поэтому используйте точные лимиты.", "glossaryTermRefs": ["approval", "allowance", "token"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Разрешение остается активным до его отзыва, даже если вы больше не пользуетесь сервисом."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Отмена подписи не отменяет уже выданный allowance."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Компрометированный контракт может вывести токены в пределах разрешения."}, {"type": "figure", "figureType": "interactive", "caption": "Интерактив: approvals sandbox", "refSlug": "approvals-sandbox"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'c1-exchanges-infra'), 'CEX vs DEX', 'cex-vs-dex', 1, '[{"type": "paragraph", "text": "CEX хранит активы пользователей и ведет учет внутри системы, DEX работает через смарт контракты и self custody. Отличие в контроле и рисках.", "glossaryTermRefs": ["cex", "dex", "custody"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Удобство CEX оплачивается доверием к оператору, а DEX требует ответственности пользователя."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "DEX не означает отсутствие рисков. Контракты и интерфейсы могут быть уязвимы."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Блокировка аккаунта на CEX приводит к потере доступа. Держите резервные каналы вывода."}, {"type": "figure", "figureType": "svg", "caption": "Сравнение CEX и DEX"}]'::jsonb),
((SELECT id FROM public.chapters WHERE slug = 'c1-exchanges-infra'), 'Ввод, вывод и выбор сети', 'deposits-withdrawals', 2, '[{"type": "paragraph", "text": "При вводе и выводе важно выбрать правильную сеть. Отправка на неверную сеть часто необратима, поэтому сверяйте адреса и комиссии.", "glossaryTermRefs": ["deposit", "withdrawal", "network"]}, {"type": "callout", "calloutType": "keyidea", "title": "Ключевая идея", "body": "Инфраструктура биржи помогает обмену, но ответственность за сеть несет пользователь."}, {"type": "callout", "calloutType": "misconception", "title": "Частое заблуждение", "body": "Совпадающий адрес не означает совместимость сетей."}, {"type": "callout", "calloutType": "threatmodel", "title": "Модель угроз", "body": "Ошибка сети приводит к потере средств или долгому восстановлению."}, {"type": "figure", "figureType": "svg", "caption": "Проверка сети перед переводом"}]'::jsonb);
INSERT INTO public.interactives (title, slug, description, embed_type, embed_url, tags, difficulty, linked_sections) VALUES
('Цифровая подпись по шагам', 'digital-signature-steps', 'Пошаговая визуализация: сообщение, хеш, подпись и проверка публичным ключом без сложной математики.', 'component', NULL, '["криптография", "подпись"]'::jsonb, 'beginner', '[]'::jsonb),
('Merkle proof Explorer', 'merkle-proof-explorer', 'Выберите лист, получите путь доказательства и проверьте включение в дерево.', 'component', NULL, '["merkle", "хеш"]'::jsonb, 'beginner', '[]'::jsonb),
('Жизненный цикл транзакции', 'transaction-lifecycle', 'Визуализация: broadcast, mempool, включение в блок, подтверждения и идея финальности.', 'component', NULL, '["сеть", "mempool"]'::jsonb, 'beginner', '[]'::jsonb),
('UTXO vs Account playground', 'utxo-vs-account', 'Один и тот же перевод в двух моделях учета: как меняется состояние.', 'component', NULL, '["utxo", "account"]'::jsonb, 'beginner', '[]'::jsonb),
('Rollup L2 flow', 'rollup-l2-flow', 'Batch, proof, settlement на L1 и компромиссы безопасности.', 'component', NULL, '["l2", "rollup"]'::jsonb, 'intermediate', '[]'::jsonb),
('Песочница approvals', 'approvals-sandbox', 'Сравнение approve unlimited и approve exact с акцентом на риски.', 'component', NULL, '["кошельки", "безопасность"]'::jsonb, 'beginner', '[]'::jsonb);
INSERT INTO public.glossary_terms (term, slug, category, short_def, full_def, related_terms, linked_sections) VALUES
('Блокчейн', 'blockchain', 'basics', 'Распределенная цепочка блоков, фиксирующая состояние системы.', 'Сеть хранит блоки с транзакциями и ссылками друг на друга. Участники могут проверять историю и состояние без центрального сервера.', '[]'::jsonb, '[]'::jsonb),
('Блок', 'block', 'basics', 'Набор транзакций и служебных данных, зафиксированный в цепочке.', 'Блок содержит заголовок и список транзакций. Он связан с предыдущим блоком через хеш.', '[]'::jsonb, '[]'::jsonb),
('Транзакция', 'transaction', 'basics', 'Запрос на изменение состояния сети.', 'Транзакция описывает кто и что делает, а сеть применяет ее по правилам протокола.', '[]'::jsonb, '[]'::jsonb),
('Состояние', 'state', 'basics', 'Текущее представление балансов и данных сети.', 'Состояние меняется при обработке транзакций и одинаково у всех честных узлов.', '[]'::jsonb, '[]'::jsonb),
('Узел', 'node', 'basics', 'Компьютер, который хранит и проверяет данные сети.', 'Узлы обмениваются блоками и транзакциями, обеспечивая устойчивость сети.', '[]'::jsonb, '[]'::jsonb),
('P2P сеть', 'p2p-network', 'basics', 'Сеть равноправных узлов без центра.', 'Каждый узел может передавать данные другим, формируя распределенную инфраструктуру.', '[]'::jsonb, '[]'::jsonb),
('Комиссия', 'fee', 'basics', 'Плата за включение транзакции в блок.', 'Комиссия компенсирует ресурсы сети и влияет на приоритет обработки.', '[]'::jsonb, '[]'::jsonb),
('Mempool', 'mempool', 'basics', 'Очередь неподтвержденных транзакций.', 'Узлы хранят mempool до включения транзакций в блок.', '[]'::jsonb, '[]'::jsonb),
('Сеть', 'network', 'basics', 'Совокупность узлов и правил взаимодействия.', 'Сеть обеспечивает распространение транзакций и блоков между участниками.', '[]'::jsonb, '[]'::jsonb),
('Пропускная способность', 'throughput', 'basics', 'Количество транзакций, которое сеть может обработать за время.', 'Ограничивается размером блоков, интервалом и вычислительными ресурсами.', '[]'::jsonb, '[]'::jsonb),
('Скалируемость', 'scalability', 'basics', 'Способность сети обслуживать больше пользователей.', 'Скалируемость требует баланса между скоростью, безопасностью и децентрализацией.', '[]'::jsonb, '[]'::jsonb),
('Подтверждение', 'confirmation', 'basics', 'Факт включения транзакции в блок.', 'Каждое подтверждение повышает уверенность, что транзакция необратима.', '[]'::jsonb, '[]'::jsonb),
('Account модель', 'account-model', 'basics', 'Модель учета с балансом на счете.', 'Account модель изменяет баланс напрямую и использует nonce против повторов.', '[]'::jsonb, '[]'::jsonb),
('Nonce', 'nonce', 'basics', 'Счетчик транзакций для защиты от повторов.', 'Nonce помогает упорядочивать транзакции и предотвращает повторное применение.', '[]'::jsonb, '[]'::jsonb),
('Gas', 'gas', 'basics', 'Мера стоимости вычислений в сети.', 'Gas оплачивает ресурсы исполнения транзакций и контрактов.', '[]'::jsonb, '[]'::jsonb),
('Токен', 'token', 'basics', 'Цифровая единица учета прав или активов.', 'Токены могут отражать доступ, голосование или ценность внутри протокола.', '[]'::jsonb, '[]'::jsonb),
('Оракул', 'oracle', 'basics', 'Источник данных из внешнего мира для контрактов.', 'Оракулы переносят доверие вне цепочки, поэтому их нужно проверять.', '[]'::jsonb, '[]'::jsonb),
('Виртуальная машина', 'virtual-machine', 'basics', 'Среда исполнения смарт контрактов.', 'Виртуальная машина обеспечивает одинаковый результат на всех узлах.', '[]'::jsonb, '[]'::jsonb),
('Смарт контракт', 'smart-contract', 'basics', 'Программируемые правила, исполняемые в сети.', 'Смарт контракт выполняется одинаково у всех узлов и хранит логику протокола.', '[]'::jsonb, '[]'::jsonb),
('UTXO', 'utxo', 'basics', 'Непотраченный выход транзакции.', 'UTXO представляет часть баланса и используется как вход для новых транзакций.', '[]'::jsonb, '[]'::jsonb),
('Хеш', 'hash', 'cryptography', 'Короткий криптографический отпечаток данных.', 'Хеш используется для проверки целостности и связывания блоков в цепочку.', '[]'::jsonb, '[]'::jsonb),
('Хеш функция', 'hash-function', 'cryptography', 'Алгоритм преобразования данных в фиксированный отпечаток.', 'Криптографические хеш функции устойчивы к коллизиям и предсказанию.', '[]'::jsonb, '[]'::jsonb),
('Коллизия хеша', 'hash-collision', 'cryptography', 'Ситуация, когда разные данные дают одинаковый хеш.', 'Надежные функции делают коллизии крайне маловероятными.', '[]'::jsonb, '[]'::jsonb),
('Хеш указатель', 'hash-pointer', 'cryptography', 'Ссылка на данные вместе с их хешем.', 'Позволяет проверить целостность данных при их получении.', '[]'::jsonb, '[]'::jsonb),
('Криптографический ключ', 'crypto-key', 'cryptography', 'Секрет или публичная часть для криптографических операций.', 'Ключи используются для подписи, шифрования и аутентификации.', '[]'::jsonb, '[]'::jsonb),
('Приватный ключ', 'private-key', 'cryptography', 'Секретный ключ для создания подписей.', 'Кто владеет приватным ключом, тот может распоряжаться активами.', '[]'::jsonb, '[]'::jsonb),
('Публичный ключ', 'public-key', 'cryptography', 'Открытая часть ключевой пары.', 'Публичный ключ позволяет проверить подпись, но не раскрывает секрет.', '[]'::jsonb, '[]'::jsonb),
('Цифровая подпись', 'digital-signature', 'cryptography', 'Криптографическое доказательство авторства сообщения.', 'Подпись подтверждает контроль над ключом и неизменность данных.', '[]'::jsonb, '[]'::jsonb),
('Эллиптическая кривая', 'elliptic-curve', 'cryptography', 'Математическая основа для ключей и подписей.', 'Эллиптические кривые позволяют создавать компактные и безопасные ключи.', '[]'::jsonb, '[]'::jsonb),
('KDF', 'kdf', 'cryptography', 'Функция вывода ключей из исходного секрета.', 'KDF повышает устойчивость ключей и добавляет соль и параметры сложности.', '[]'::jsonb, '[]'::jsonb),
('Соль', 'salt', 'cryptography', 'Случайная добавка для усиления ключей.', 'Соль предотвращает повторное использование одинаковых ключей и атак по словарю.', '[]'::jsonb, '[]'::jsonb),
('Энтропия', 'entropy', 'cryptography', 'Мера случайности входных данных.', 'Высокая энтропия делает ключи непредсказуемыми.', '[]'::jsonb, '[]'::jsonb),
('Merkle дерево', 'merkle-tree', 'cryptography', 'Дерево хешей для компактной проверки данных.', 'Позволяет доказать включение элемента без раскрытия всего набора.', '[]'::jsonb, '[]'::jsonb),
('Merkle proof', 'merkle-proof', 'cryptography', 'Путь хешей для проверки элемента в Merkle дереве.', 'Используется в легких клиентах и проверке блоков.', '[]'::jsonb, '[]'::jsonb),
('Симметричное шифрование', 'symmetric-encryption', 'cryptography', 'Шифрование одним общим ключом.', 'Используется для хранения данных, но не решает задачу распределения ключей.', '[]'::jsonb, '[]'::jsonb),
('Асимметричное шифрование', 'asymmetric-encryption', 'cryptography', 'Шифрование с парой ключей.', 'Публичный ключ шифрует, приватный расшифровывает данные.', '[]'::jsonb, '[]'::jsonb),
('Сигнатура сообщения', 'message-signature', 'cryptography', 'Подпись произвольного сообщения вне транзакции.', 'Часто используется для входа или подтверждения владения адресом.', '[]'::jsonb, '[]'::jsonb),
('Хеш тайм лок', 'hash-time-lock', 'cryptography', 'Условие расходования средств по хешу и времени.', 'Используется в платежных каналах и атомарных свопах.', '[]'::jsonb, '[]'::jsonb),
('Консенсус', 'consensus', 'consensus', 'Механизм согласования истории блоков между узлами.', 'Консенсус обеспечивает единое состояние сети даже при недоверии между участниками.', '[]'::jsonb, '[]'::jsonb),
('Proof of Work', 'proof-of-work', 'consensus', 'Модель, где право на блок дается за вычислительную работу.', 'Майнеры решают задачу и получают вознаграждение, обеспечивая безопасность.', '[]'::jsonb, '[]'::jsonb),
('Proof of Stake', 'proof-of-stake', 'consensus', 'Модель, где блоки создают валидаторы с залогом.', 'Участники ставят активы и несут риск штрафов за нарушения.', '[]'::jsonb, '[]'::jsonb),
('Валидатор', 'validator', 'consensus', 'Участник, предлагающий и подтверждающий блоки.', 'Валидаторы следуют правилам протокола и получают награды.', '[]'::jsonb, '[]'::jsonb),
('Майнер', 'miner', 'consensus', 'Участник, выполняющий вычисления в PoW.', 'Майнеры соревнуются за право создать новый блок.', '[]'::jsonb, '[]'::jsonb),
('Слот', 'slot', 'consensus', 'Временной интервал для предложений блоков.', 'В PoS сети блоки организованы по слотам и эпохам.', '[]'::jsonb, '[]'::jsonb),
('Эпоха', 'epoch', 'consensus', 'Группа слотов с общими параметрами.', 'Эпохи помогают организовать ротацию валидаторов и начисление наград.', '[]'::jsonb, '[]'::jsonb),
('Сложность', 'difficulty', 'consensus', 'Параметр, задающий трудность вычислений в PoW.', 'Сложность регулирует скорость выпуска блоков.', '[]'::jsonb, '[]'::jsonb),
('Reorg', 'reorg', 'consensus', 'Перестройка цепочки при появлении альтернативной истории.', 'Reorg возможен при конкурирующих блоках и задержках в сети.', '[]'::jsonb, '[]'::jsonb),
('Атака 51 процента', 'attack-51', 'consensus', 'Контроль большинства хешрейта или стейка.', 'Позволяет переписывать историю и цензурировать транзакции.', '[]'::jsonb, '[]'::jsonb),
('Sybil атака', 'sybil-attack', 'consensus', 'Создание множества псевдоузлов для влияния.', 'Консенсус защищается экономическими затратами на участие.', '[]'::jsonb, '[]'::jsonb),
('Награда за блок', 'block-reward', 'consensus', 'Компенсация за создание блока.', 'Награда может состоять из эмиссии и комиссий.', '[]'::jsonb, '[]'::jsonb),
('Слэшинг', 'slashing', 'consensus', 'Штраф за нарушение правил валидатором.', 'Слэшинг уменьшает стимулы к атаке и бездействию.', '[]'::jsonb, '[]'::jsonb),
('Двойная трата', 'double-spend', 'consensus', 'Попытка потратить одни и те же средства дважды.', 'Консенсус предотвращает это за счет подтверждений и правил.', '[]'::jsonb, '[]'::jsonb),
('Ливнесс', 'liveness', 'consensus', 'Свойство сети продолжать обработку транзакций.', 'Важно для доступности и устойчивости к сбоям.', '[]'::jsonb, '[]'::jsonb),
('Safety', 'safety', 'consensus', 'Свойство сети не принимать противоречивые блоки.', 'Safety и liveness нужно балансировать в протоколе.', '[]'::jsonb, '[]'::jsonb),
('BFT', 'bft', 'consensus', 'Класс алгоритмов устойчивых к ошибкам.', 'BFT протоколы обеспечивают согласование даже при злонамеренных узлах.', '[]'::jsonb, '[]'::jsonb),
('Кошелек', 'wallet', 'wallets', 'Инструмент для управления ключами и транзакциями.', 'Кошелек хранит ключи и помогает подписывать операции в сети.', '[]'::jsonb, '[]'::jsonb),
